import { Button } from "@/components/ui/button";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { dialogManager } from "@/features/dialog-manager/dialog-manager";
import {
  saveDrawingInspirationRef,
  uploadInspirationImageRef,
} from "@/features/inspiration/inspiration.convex";
import { cn } from "@/lib/utils";
import { useBlocker, useNavigate } from "@tanstack/react-router";
import { useAction as useConvexAction, useMutation as useConvexMutation } from "convex/react";
import {
  ArrowUpRight,
  Circle,
  ImagePlus,
  Loader2,
  MousePointer2,
  Pencil,
  Redo2,
  Square,
  Type,
  Undo2,
  UserRound,
  LayoutTemplate,
} from "lucide-react";
import { nanoid } from "nanoid";
import {
  useEffect,
  useRef,
  useState,
  type PointerEvent as ReactPointerEvent,
} from "react";
import { toast } from "sonner";
import {
  arrowBoxFromPoints,
  boxFromPoints,
  centerOf,
  hitTest,
  hitTestHandle,
  pencilFromPoints,
  resizeObject,
  rotateObject,
  translateObject,
  type Handle,
} from "./drawing-geometry";
import { renderDrawingPng } from "./drawing-export";
import {
  arrowGeometry,
  pencilPolyline,
  personGeometry,
  roughEllipsePath,
  roughRectPath,
} from "./drawing-rough";
import {
  DRAWING_FILLS,
  DRAWING_FONT,
  DRAWING_HEIGHT,
  DRAWING_STROKE_WIDTHS,
  DRAWING_STROKES,
  DRAWING_WIDTH,
  describeDrawing,
  serializeDrawing,
  type ArrowObject,
  type DrawingDocument,
  type DrawingObject,
  type DrawingTool,
  type EllipseObject,
  type ImageObject,
  type PersonObject,
  type Point,
  type RectObject,
  type ShapeStyle,
  type TextObject,
} from "./drawing.schema";
import { DRAWING_TEMPLATES, documentFromTemplate } from "./drawing-templates";

type DrawingEditorProps = {
  orgSlug: string;
  inspirationId?: string;
  initialDocument: DrawingDocument;
  initialName: string;
};

type DragState =
  | {
      kind: "move";
      origin: Point;
      snapshots: DrawingObject[];
      startDoc: DrawingDocument;
      moved: boolean;
    }
  | {
      kind: "resize";
      handle: Exclude<Handle, "rotate">;
      snapshot: DrawingObject;
      startDoc: DrawingDocument;
    }
  | {
      kind: "rotate";
      snapshot: DrawingObject;
      startPoint: Point;
      startDoc: DrawingDocument;
    }
  | {
      kind: "shape";
      tool: "rect" | "ellipse" | "arrow";
      origin: Point;
      object: DrawingObject;
      startDoc: DrawingDocument;
    }
  | {
      kind: "pencil";
      points: Point[];
      startDoc: DrawingDocument;
    }
  | {
      kind: "person";
      origin: Point;
      object: PersonObject;
      startDoc: DrawingDocument;
      moved: boolean;
    };

const TOOLS: Array<{ id: DrawingTool; label: string; shortcut: string }> = [
  { id: "select", label: "Select", shortcut: "V" },
  { id: "text", label: "Text", shortcut: "T" },
  { id: "arrow", label: "Arrow", shortcut: "A" },
  { id: "rect", label: "Rectangle", shortcut: "R" },
  { id: "ellipse", label: "Circle", shortcut: "O" },
  { id: "pencil", label: "Pencil", shortcut: "P" },
  { id: "person", label: "Person", shortcut: "S" },
];

export function DrawingEditor({
  orgSlug,
  inspirationId,
  initialDocument,
  initialName,
}: DrawingEditorProps) {
  const navigate = useNavigate();
  const uploadImage = useConvexAction(uploadInspirationImageRef);
  const saveDrawing = useConvexMutation(saveDrawingInspirationRef);
  const [document, setDocument] = useState(initialDocument);
  const [name, setName] = useState(initialName);
  const [tool, setTool] = useState<DrawingTool>("select");
  const [selection, setSelection] = useState<string[]>([]);
  const [style, setStyle] = useState<ShapeStyle>({
    stroke: DRAWING_STROKES[0],
    fill: "transparent",
    strokeWidth: 4,
  });
  const [draft, setDraft] = useState<DrawingObject | null>(null);
  const [editingText, setEditingText] = useState<{
    id: string;
    text: string;
    startDoc: DrawingDocument;
  } | null>(null);
  const [saving, setSaving] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [saveError, setSaveError] = useState<string | null>(null);
  const [historyTick, setHistoryTick] = useState(0);
  const [handleRadius, setHandleRadius] = useState(12);
  const svgRef = useRef<SVGSVGElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const docRef = useRef(document);
  const dragRef = useRef<DragState | null>(null);
  const pastRef = useRef<DrawingDocument[]>([]);
  const futureRef = useRef<DrawingDocument[]>([]);
  const savedRef = useRef(serializeDrawing(initialDocument));
  const savedNameRef = useRef(initialName);
  const nameRef = useRef(name);
  nameRef.current = name;
  const blocker = useBlocker({
    withResolver: true,
    enableBeforeUnload: false,
    shouldBlockFn: () =>
      serializeDrawing(docRef.current) !== savedRef.current ||
      nameRef.current.trim() !== savedNameRef.current.trim(),
  });
  const blockerRef = useRef(blocker);
  blockerRef.current = blocker;
  const clipboardRef = useRef<DrawingObject[]>([]);
  const pasteCountRef = useRef(0);
  const selectionRef = useRef(selection);
  const toolRef = useRef(tool);
  const styleRef = useRef(style);
  const editingRef = useRef(editingText);

  docRef.current = document;
  selectionRef.current = selection;
  toolRef.current = tool;
  styleRef.current = style;
  editingRef.current = editingText;

  const dirty =
    serializeDrawing(document) !== savedRef.current ||
    name.trim() !== savedNameRef.current.trim();

import { DrawingEditor } from "@/features/drawing/drawing-editor";
import {
  createEmptyDrawing,
  parseDrawingDocument,
} from "@/features/drawing/drawing.schema";
import { useInspiration } from "@/features/inspiration/inspiration.query";
import { Button } from "@/components/ui/button";
import Link from "@/compat/link";
import { createFileRoute } from "@tanstack/react-router";
import { Loader2 } from "lucide-react";

type DrawSearch = {
  inspirationId?: string;
};

export const Route = createFileRoute("/orgs/$orgSlug/inspirations/draw")({
  validateSearch: (search: Record<string, unknown>): DrawSearch => ({
    inspirationId:
      typeof search.inspirationId === "string" && search.inspirationId
        ? search.inspirationId
        : undefined,
  }),
  component: DrawInspirationPage,
});

function DrawInspirationPage() {
  const { orgSlug } = Route.useParams();
  const { inspirationId } = Route.useSearch();

  if (!inspirationId) {
    return (
      <DrawingEditor
        key="new-drawing"
        orgSlug={orgSlug}
        initialDocument={createEmptyDrawing()}
        initialName="Drawing inspiration"
      />
    );
  }

  return <EditDrawingPage orgSlug={orgSlug} inspirationId={inspirationId} />;
}

function EditDrawingPage({
  orgSlug,
  inspirationId,
}: {
  orgSlug: string;
  inspirationId: string;
}) {
  const { data, isLoading } = useInspiration(orgSlug, inspirationId);
  const backHref = `/orgs/${orgSlug}/inspirations`;

  if (isLoading || !data) {
    return (
      <div className="flex h-dvh flex-col items-center justify-center gap-3 bg-[#eceae4]">
        <h1 className="text-lg font-semibold">Grok 4.7</h1>
        <Loader2 className="size-5 animate-spin" />
        <p className="text-sm text-[#57534e]">Loading drawing...</p>
      </div>
    );
  }

  const document = parseDrawingDocument(data.drawing);
  if (!data.hasDrawing || !document) {
    return (
      <div className="flex h-dvh flex-col items-center justify-center gap-4 bg-[#eceae4] px-6 text-center">
        <h1 className="text-lg font-semibold">Grok 4.7</h1>
        <p className="max-w-md text-sm text-[#57534e]">
          This inspiration does not have an editable drawing.
        </p>
        <Button asChild>
          <Link href={backHref}>Back to inspirations</Link>
        </Button>
      </div>
    );
  }

  return (
    <DrawingEditor
      key={inspirationId}
      orgSlug={orgSlug}
      inspirationId={inspirationId}
      initialDocument={document}
      initialName={data.name}
    />
  );
}

