export const saveDrawing = mutation({
  args: {
    orgSlug: v.string(),
    inspirationId: v.optional(v.string()),
    name: v.string(),
    description: v.optional(v.string()),
    previewUrl: v.string(),
    drawing: v.string(),
  },
  handler: async (ctx, args) => {
    const appCtx = ctx as unknown as AppCtx;
    const { org } = await requireOrg(appCtx, args.orgSlug);
    const document = assertDrawingDocument(args.drawing);
    const previewUrl = args.previewUrl.trim();
    if (!/^https?:\/\//.test(previewUrl)) {
      throw new Error("Preview image is required");
    }

    const name = args.name.trim().slice(0, 120) || "Drawing inspiration";
    const description = (
      args.description?.trim() || describeDrawing(document)
    ).slice(0, 2000);
    const drawing = JSON.stringify(document);
    const now = Date.now();
    const image = storedImage(previewUrl, "image/png");

    if (args.inspirationId) {
      const id = ctx.db.normalizeId("inspirations", args.inspirationId);
      if (!id) throw new Error("Inspiration not found");
      const existing = await ctx.db.get(id);
      if (!existing || existing.organizationId !== org.id || existing.deletedAt) {
        throw new Error("Inspiration not found");
      }
      if (!existing.drawing) {
        throw new Error("This inspiration is not a drawing");
      }
      await ctx.db.patch(id, {
        title: name,
        description,
        image,
        images: [image],
        drawing,
        categories: existing.categories ?? ["Other"],
        ...resetReviewAfterOwnerEdit(existing),
        updatedAt: now,
      });
      const updated = await ctx.db.get(id);
      if (!updated) throw new Error("Inspiration not found");
      return toInspirationRow(updated, { includeDrawing: true });
    }

    const rows = await ctx.db
      .query("inspirations")
      .withIndex("by_organization", (q: any) => q.eq("organizationId", org.id))
      .take(MAX_ROWS);
    const currentCount = rows.filter((row: InspirationRow) => !row.deletedAt).length;
    const subscription = await getActiveSubscription(appCtx, org.id);
    const maxInspirations = getPlanLimitsWithOverrides(
      subscription?.plan,
      subscription?.overrideLimits,
    ).maxInspirations;
    if (currentCount >= maxInspirations) {
      throw new Error(
        `You have reached your limit of ${maxInspirations} inspirations. Upgrade to create more.`,
      );
    }

    const id = await ctx.db.insert("inspirations", {
      organizationId: org.id,
      title: name,
      description,
      image,
      images: [image],
      drawing,
      categories: ["Other"],
      hasPlaceholder: false,
      anonymizedSubject: false,
      anonymizedText: false,
      anonymizedLogos: false,
      isPublic: false,
      adminReview: REVIEW_STATUS.PENDING,
      createdAt: now,
      updatedAt: now,
    });
    const created = await ctx.db.get(id);
    if (!created) throw new Error("Inspiration not found");
    return toInspirationRow(created, { includeDrawing: true });
  },
});

export const createUploadedWithoutAnalysis = mutation({
  args: {
    orgSlug: v.string(),
    imageUrls: v.array(v.string()),
    sourceUrl: v.optional(v.string()),
    hasPlaceholder: v.optional(v.boolean()),
  },
  handler: async (ctx, args) => {
    return ctx.runMutation(createFromUploadedUrlsRef, {
      ...args,
      title: "Imported inspiration",
      description: "",
      category: "Other",
    });
  },
});

export const updateName = mutation({
  args: {
    orgSlug: v.string(),
    inspirationId: v.string(),
    name: v.string(),
  },
  handler: async (ctx, args) => {
    const { org } = await requireOrg(ctx as unknown as AppCtx, args.orgSlug);
    const id = ctx.db.normalizeId("inspirations", args.inspirationId);
    if (!id) throw new Error("Inspiration not found");
    const inspiration = id ? await ctx.db.get(id) : null;
    if (!inspiration || inspiration.organizationId !== org.id) {
      throw new Error("Inspiration not found");
    }
    const name = args.name.trim();
    if (!name) throw new Error("Name is required");
    await ctx.db.patch(id, {
      title: name,
      ...resetReviewAfterOwnerEdit(inspiration),
      updatedAt: Date.now(),
    });
    return { id: args.inspirationId, name };
  },
});

export const updateImages = mutation({
  args: {
    orgSlug: v.string(),
    inspirationId: v.string(),
    thumbnailUrls: v.array(v.string()),
    isPublic: v.optional(v.boolean()),
  },
  handler: async (ctx, args) => {
    const { org } = await requireOrg(ctx as unknown as AppCtx, args.orgSlug);
    const id = ctx.db.normalizeId("inspirations", args.inspirationId);
    if (!id) throw new Error("Inspiration not found");
    const inspiration = id ? await ctx.db.get(id) : null;
    if (!inspiration || inspiration.organizationId !== org.id) {
      throw new Error("Inspiration not found");
    }
    const images = args.thumbnailUrls
      .filter(Boolean)
      .map((url) => storedImage(url));
    if (images.length === 0) throw new Error("At least one image is required");
    await ctx.db.patch(id, {
      image: images[0],
      images,
      hasPlaceholder: false,
      anonymizedSubject: false,
      anonymizedText: false,
      anonymizedLogos: false,
      anonymizedTextDescription: undefined,
      ...resetReviewAfterOwnerEdit(inspiration),
      ...(args.isPublic != null ? { isPublic: args.isPublic } : {}),
      updatedAt: Date.now(),
    });
    const updated = await ctx.db.get(id);

  name.trim() !== savedNameRef.current.trim();
const canUndo = historyTick >= 0 && pastRef.current.length > 0;
const canRedo = historyTick >= 0 && futureRef.current.length > 0;
const selected = document.objects.filter((object) =>
  selection.includes(object.id),
);
const single = selected.length === 1 ? selected[0] : null;

useEffect(() => {
  if (blocker.status !== "blocked") return;
  dialogManager.confirm({
    title: "Discard this drawing?",
    description: "You have unsaved changes on this inspiration.",
    variant: "destructive",
    action: {
      label: "Discard",
      variant: "destructive",
      onClick: () => blockerRef.current.proceed?.(),
    },
    cancel: {
      label: "Keep editing",
      onClick: () => blockerRef.current.reset?.(),
    },
  });
}, [blocker.status]);

useEffect(() => {
  const onBeforeUnload = (event: BeforeUnloadEvent) => {
    if (
      serializeDrawing(docRef.current) === savedRef.current &&
      name.trim() === savedNameRef.current.trim()
    ) {
      return;
    }
    event.preventDefault();
    event.returnValue = "";
  };
  window.addEventListener("beforeunload", onBeforeUnload);
  return () => window.removeEventListener("beforeunload", onBeforeUnload);
}, [name]);

useEffect(() => {
  const svg = svgRef.current;
  if (!svg || typeof ResizeObserver === "undefined") return;
  const update = () => {
    const width = svg.getBoundingClientRect().width;
    if (width > 0) setHandleRadius((12 / width) * DRAWING_WIDTH);
  };
  update();
  const observer = new ResizeObserver(update);
  observer.observe(svg);
  return () => observer.disconnect();
}, []);

useEffect(() => {
  const onKeyDown = (event: KeyboardEvent) => {
    if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      if (isTypingTarget(event.target)) {
        (event.target as HTMLElement).blur();
        return;
      }
      if (editingRef.current) {
        commitTextEdit();
        return;
      }
      setSelection([]);
      return;
    }

    if (isTypingTarget(event.target)) return;

    const meta = event.metaKey || event.ctrlKey;
    if (meta && event.key.toLowerCase() === "z") {
      event.preventDefault();
      if (event.shiftKey) redo();
      else undo();
      return;
    }
    if (meta && event.key.toLowerCase() === "y") {
      event.preventDefault();
      redo();
      return;
    }
    if (meta && event.key.toLowerCase() === "c") {
      event.preventDefault();
      copySelection();
      return;
    }
    if (meta && event.key.toLowerCase() === "v") {
      event.preventDefault();
      pasteClipboard();
      return;
    }
    if (meta && event.key.toLowerCase() === "d") {
      event.preventDefault();
      duplicateSelection();
      return;
    }
    if (meta && event.key.toLowerCase() === "a") {
      event.preventDefault();
      setSelection(docRef.current.objects.map((object) => object.id));
      return;
    }
    if (event.key === "Delete" || event.key === "Backspace") {
      event.preventDefault();
      deleteSelection();
      return;
    }

    const shortcut = event.key.toLowerCase();
    const nextTool = TOOLS.find((item) => item.shortcut.toLowerCase() === shortcut);
    if (nextTool && !meta && !event.altKey) {
      event.preventDefault();
      setTool(nextTool.id);
    }
  };

  window.addEventListener("keydown", onKeyDown);
  return () => window.removeEventListener("keydown", onKeyDown);
});

const leave = () => {
  void navigate({ to: `/orgs/${orgSlug}/inspirations` });
};

const requestLeave = () => {
  leave();
};

const save = async () => {
  if (saving || uploading) return;
  setSaving(true);
  setSaveError(null);
  try {
    commitTextEdit();
    const bytes = await renderDrawingPng(docRef.current);
    const previewUrl = await uploadImage({
      orgSlug,
      bytes,
      fileName: "drawing-preview.png",
      contentType: "image/png",
    });
    const saved = await saveDrawing({
      orgSlug,
      inspirationId,
      name: name.trim() || "Drawing inspiration",
      description: describeDrawing(docRef.current),
      previewUrl,
      drawing: serializeDrawing(docRef.current),
    });
    savedRef.current = serializeDrawing(docRef.current);
    savedNameRef.current = name.trim() || "Drawing inspiration";
    toast.success(inspirationId ? "Drawing updated" : "Inspiration created");
    void navigate({
      to: `/orgs/${orgSlug}/inspirations/${saved.id}`,
    });
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Could not save the drawing";
    setSaveError(message);
    toast.error(message);
  } finally {
    setSaving(false);
  }
};

const onPointerDown = (event: ReactPointerEvent<SVGSVGElement>) => {
  if (event.button !== 0) return;
  if (editingRef.current) commitTextEdit();
  const point = canvasPoint(event);
  const activeTool = toolRef.current;
  try {
    svgRef.current?.setPointerCapture(event.pointerId);
  } catch {
    // Some environments cannot capture the pointer. Dragging still tracks move events.
  }

  if (activeTool === "select") {
    const only = selectionRef.current.length === 1
      ? docRef.current.objects.find((object) => object.id === selectionRef.current[0])
      : undefined;
    if (only) {
      const handle = hitTestHandle(only, point, handleRadius);
      if (handle === "rotate") {
        dragRef.current = {
          kind: "rotate",
          snapshot: only,
          startPoint: point,
          startDoc: docRef.current,
        };
        return;
      }
      if (handle) {
        dragRef.current = {
          kind: "resize",
          handle,
          snapshot: only,
          startDoc: docRef.current,
        };
        return;
      }
    }

    const hit = hitTest(docRef.current.objects, point);
    let nextSelection = selectionRef.current;
    if (event.shiftKey && hit) {
      nextSelection = nextSelection.includes(hit.id)
        ? nextSelection.filter((id) => id !== hit.id)
        : [...nextSelection, hit.id];
    } else if (hit) {
      nextSelection = nextSelection.includes(hit.id) ? nextSelection : [hit.id];
    } else {
      nextSelection = [];
    }
    setSelection(nextSelection);
    const snapshots = docRef.current.objects.filter((object) =>
      nextSelection.includes(object.id),
    );
    if (hit && snapshots.length > 0) {
      dragRef.current = {
        kind: "move",
        origin: point,
        snapshots,
        startDoc: docRef.current,
        moved: false,
      };
    }
    return;
  }

  if (activeTool === "text") {
    const object = createText(point, styleRef.current);
    updateDocument((current) => ({
      ...current,
      objects: [...current.objects, object],
    }));
    setSelection([object.id]);
    setEditingText({ id: object.id, text: object.text, startDoc: docRef.current });
    setTool("select");
    return;
  }

  if (activeTool === "pencil") {
    dragRef.current = {
      kind: "pencil",
      points: [point],
      startDoc: docRef.current,
    };
    setDraft(
      pencilFromPoints(nanoid(10), [point], styleRef.current.stroke, styleRef.current.strokeWidth),
    );
    return;
  }

  if (activeTool === "person") {
    const object = createPerson(point, styleRef.current, 300, 420);
    dragRef.current = {
      kind: "person",
      origin: point,
      object,
      startDoc: docRef.current,
      moved: false,
    };
    setDraft(object);
    return;
  }

  const object = createShape(activeTool, point, point, false, styleRef.current);
  dragRef.current = {
    kind: "shape",
    tool: activeTool,
    origin: point,
    object,
    startDoc: docRef.current,
  };
  setDraft(object);
};

const onPointerMove = (event: ReactPointerEvent<SVGSVGElement>) => {
  const drag = dragRef.current;
  if (!drag) return;
  const point = canvasPoint(event);

  if (drag.kind === "move") {
    const dx = point.x - drag.origin.x;
    const dy = point.y - drag.origin.y;
    if (Math.hypot(dx, dy) < 2 && !drag.moved) return;
    drag.moved = true;
    setLive(
      replaceObjects(
        drag.startDoc,
        drag.snapshots.map((object) => translateObject(object, dx, dy)),
      ),
    );
    return;
  }

  if (drag.kind === "resize") {
    setLive(
      replaceObjects(drag.startDoc, [
        resizeObject(drag.snapshot, drag.handle, point, event.shiftKey),
      ]),
    );
    return;
  }

  if (drag.kind === "rotate") {
    setLive(
      replaceObjects(drag.startDoc, [
        rotateObject(drag.snapshot, point, drag.startPoint, event.shiftKey),
      ]),
    );
    return;
  }

  if (drag.kind === "shape") {
    const object = createShape(
      drag.tool,
      drag.origin,
      point,
      event.shiftKey,
      styleRef.current,
      drag.object.id,
    );
    drag.object = object;
    setDraft(object);
    return;
  }

  if (drag.kind === "pencil") {
    const last = drag.points[drag.points.length - 1];
    if (!last || Math.hypot(point.x - last.x, point.y - last.y) > 1.5) {
      drag.points.push(point);
    }
    setDraft(
      pencilFromPoints(
        "draft-pencil",
        drag.points,
        styleRef.current.stroke,
        styleRef.current.strokeWidth,
      ),
    );
    return;
  }

  const distance = Math.hypot(point.x - drag.origin.x, point.y - drag.origin.y);
  if (distance < 6) return;
  drag.moved = true;
  const box = boxFromPoints(drag.origin, point, event.shiftKey);
  const object = {
    ...drag.object,
    ...box,
  };
  drag.object = object;
  setDraft(object);
};

const onPointerUp = () => {
  const drag = dragRef.current;
  dragRef.current = null;
  if (!drag) return;

  if (drag.kind === "move" || drag.kind === "resize" || drag.kind === "rotate") {
    finishGesture(drag.startDoc);
    return;
  }

  if (drag.kind === "pencil") {
    const object = pencilFromPoints(
      nanoid(10),
      drag.points,
      styleRef.current.stroke,
      styleRef.current.strokeWidth,
    );
    setDraft(null);
    if (!object || drag.points.length < 2) return;
    updateDocument((current) => ({
      ...current,
      objects: [...current.objects, object],
    }));
    setSelection([object.id]);
    return;
  }

  if (drag.kind === "person") {
    setDraft(null);
    const id = nanoid(10);
    const object = drag.moved
      ? {
          ...drag.object,
          id,
          width: Math.max(80, drag.object.width),
          height: Math.max(100, drag.object.height),
        }
      : { ...createPerson(drag.origin, styleRef.current, 300, 420), id };
    updateDocument((current) => ({
      ...current,
      objects: [...current.objects, object],
    }));
    setSelection([id]);
    setTool("select");
    return;
  }

  setDraft(null);
  if (drag.object.width < 6 || drag.object.height < 6) return;
  updateDocument((current) => ({
    ...current,
    objects: [...current.objects, drag.object],
  }));
  setSelection([drag.object.id]);
};

const onDoubleClick = (event: ReactPointerEvent<SVGSVGElement>) => {
  const hit = hitTest(docRef.current.objects, canvasPoint(event));
  if (!hit || hit.type !== "text") return;
  setSelection([hit.id]);
  setEditingText({ id: hit.id, text: hit.text, startDoc: docRef.current });
};

const commitTextEdit = () => {
  const editing = editingRef.current;
  if (!editing) return;
  editingRef.current = null;
  setEditingText(null);
  if (serializeDrawing(editing.startDoc) === serializeDrawing(docRef.current)) return;
  pastRef.current.push(editing.startDoc);
  if (pastRef.current.length > 80) pastRef.current.shift();
  futureRef.current = [];
  setHistoryTick((tick) => tick + 1);
};

const updateTextDraft = (text: string) => {
  setEditingText((current) => (current ? { ...current, text } : current));
  setLive({
    ...docRef.current,
    objects: docRef.current.objects.map((object) =>
      object.id === editingRef.current?.id && object.type === "text"
        ? { ...object, text }
        : object,
    ),
  });
};

