function SceneObject({
  object,
  editing = false,
  editingText = "",
  onTextChange,
  onTextCommit,
}: {
  object: DrawingObject;
  editing?: boolean;
  editingText?: string;
  onTextChange?: (text: string) => void;
  onTextCommit?: () => void;
}) {
  const center = centerOf(object);
  return (
    <g transform={`rotate(${object.rotation} ${center.x} ${center.y})`}>
      {object.type === "rect" ? (
        <path
          d={roughRectPath(object.x, object.y, object.width, object.height, object.id)}
          fill={object.fill}
          stroke={object.stroke}
          strokeWidth={object.strokeWidth}
          strokeLinejoin="round"
        />
      ) : null}
      {object.type === "ellipse" ? (
        <path
          d={roughEllipsePath(object.x, object.y, object.width, object.height, object.id)}
          fill={object.fill}
          stroke={object.stroke}
          strokeWidth={object.strokeWidth}
        />
      ) : null}
      {object.type === "arrow" ? <ArrowShape object={object} /> : null}
      {object.type === "pencil" ? (
        <path
          d={pencilPolyline(object)}
          fill="none"
          stroke={object.stroke}
          strokeWidth={object.strokeWidth}
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      ) : null}
      {object.type === "image" ? (
        <image
          href={object.src}
          x={object.x}
          y={object.y}
          width={object.width}
          height={object.height}
          preserveAspectRatio="xMidYMid slice"
        />
      ) : null}
      {object.type === "person" ? <PersonShape object={object} /> : null}
      {object.type === "text" ? (
        <foreignObject
          x={object.x}
          y={object.y}
          width={object.width}
          height={object.height}
        >
          {editing ? (
            <textarea
              aria-label="Edit text"
              autoFocus
              value={editingText}
              onChange={(event) => onTextChange?.(event.target.value)}
              onBlur={() => onTextCommit?.()}
              onPointerDown={(event) => event.stopPropagation()}
              onKeyDown={(event) => {
                if (event.key === "Escape") {
                  event.preventDefault();
                  event.stopPropagation();
                  event.currentTarget.blur();
                }
              }}
              className="h-full w-full resize-none border-0 bg-transparent p-0 outline-none"
              style={{
                color: object.color,
                fontSize: object.fontSize,
                fontFamily: DRAWING_FONT,
                lineHeight: 1.15,
              }}
            />
          ) : (
            <div
              className="pointer-events-none h-full w-full overflow-hidden whitespace-pre-wrap"
              style={{
                color: object.color,
                fontSize: object.fontSize,
                fontFamily: DRAWING_FONT,
                lineHeight: 1.15,
              }}
            >
              {object.text}
            </div>
          )}
        </foreignObject>
      ) : null}
    </g>
  );
}

